export function getRulePack(year: number): RulePackMetadata {
  const pack = FEDERAL_RULE_PACKS[year];
  if (!pack) throw new Error(`Unknown tax year ${year}. Known years: ${Object.keys(FEDERAL_RULE_PACKS).join(", ")}`);
  return pack;
}
